<x-layouts::app :title="$task->title"><div class="mx-auto flex max-w-3xl flex-col gap-4 p-4 md:p-8"><div class="flex items-center justify-between"><h1 class="text-2xl font-semibold">{{ $task->title }}</h1>@can('update',$task)<a class="rounded-lg border px-4 py-2" href="{{ route('tasks.edit',$task) }}">Edit</a>@endcan</div>@if(session('status'))<p class="rounded-lg bg-green-100 p-3 text-green-800">{{ session('status') }}</p>@endif<div class="grid gap-3 rounded-xl border p-5 sm:grid-cols-2"><p><b>Employee:</b> {{ $task->employee->name }}</p><p><b>Manager:</b> {{ $task->manager->name }}</p><p><b>Priority:</b> {{ $task->priority }}</p><p><b>Status:</b> {{ $task->status }} @if($task->isOverdue()) <span class="text-red-600">Overdue</span>@endif</p><p><b>Start:</b> {{ $task->start_date?->format('M j, Y') ?? '—' }}</p><p><b>Due:</b> {{ $task->due_date?->format('M j, Y') ?? '—' }}</p><p><b>Completed:</b> {{ $task->completed_at?->format('M j, Y H:i') ?? '—' }}</p><p class="sm:col-span-2"><b>Description:</b><br>{{ $task->description ?? 'No description.' }}</p></div>@if(auth()->user()->hasRole('Employee'))<form method="POST" action="{{ route('tasks.update',$task) }}" class="flex items-center gap-3">@csrf @method('PUT')<select name="status" class="rounded-lg border bg-transparent p-2">@foreach(['To Do','In Progress','Completed','Blocked'] as $status)<option @selected($task->status===$status)>{{ $status }}</option>@endforeach</select><button class="rounded-lg bg-blue-600 px-4 py-2 text-white">Update status</button></form>@endif@can('delete',$task)<form method="POST" action="{{ route('tasks.destroy',$task) }}" onsubmit="return confirm('Delete this task?')">@csrf @method('DELETE')<button class="text-red-600">Delete task</button></form>@endcan</div></x-layouts::app>
